"""Render a MachineConfig as NixOS configuration text.

This is the canonical meaning of a `MachineConfig`: what the server declared, written
as the Nix a machine can actually rebuild from. The agent writes the result to
`/etc/nixos/nixync.nix`; the host app renders the same text as a preview, which is why
this lives in the shared client library rather than in either application.

Nothing here touches the filesystem.
"""

import re

from nixync_client.protocol import LocalUser, MachineConfig, SystemSettings

HEADER = (
    "# Generated by Nixync. Edit your fleet from the Nixync app, not this file —\n"
    "# it is overwritten on every deployment.\n"
)

# Nixpkgs attribute names and POSIX user names. Deliberately narrow.
SAFE_NAME = re.compile(r"^[A-Za-z0-9._-]+$")


class InvalidPackageName(ValueError):
    """A name that cannot be safely written into Nix."""


def _checked(name: str, kind: str) -> str:
    """Validate rather than escape.

    Escaping would let a hostile name through in some encoded form. These names come
    from an unauthenticated server, and anything outside the character set is either a
    typo or an attempt to inject Nix — neither should reach a machine.
    """
    if not SAFE_NAME.match(name):
        raise InvalidPackageName(f"unsafe {kind} name: {name!r}")
    return name


def _b(value: bool) -> str:
    return "true" if value else "false"


def _nix_string(text: str) -> str:
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _render_user(user: LocalUser) -> list[str]:
    name = _checked(user.name, "user")
    groups = ' [ "wheel" ]' if user.admin else " [ ]"
    lines = [
        f"  users.users.{name} = {{",
        "    isNormalUser = true;",
    ]
    if user.full_name:
        lines.append(f"    description = {_nix_string(user.full_name)};")
    lines.append(f"    extraGroups ={groups};")
    # No password, by design: it is set on the device and hashed there. A hash in the
    # Nix store is world-readable, so it must never be rendered here.
    lines.append("  };")
    return lines


def _render_settings(s: SystemSettings) -> list[str]:
    nameservers = " ".join(_nix_string(n) for n in s.nameservers)
    ports = " ".join(str(int(p)) for p in s.open_tcp_ports)
    lines = []
    if s.hostname:
        # An empty hostname is a real NixOS setting and never what anyone meant.
        lines.append(f"  networking.hostName = {_nix_string(s.hostname)};")
    lines += [
        f"  networking.nameservers = [ {nameservers} ];",
        f"  networking.firewall.enable = {_b(s.firewall)};",
        f"  networking.firewall.allowedTCPPorts = [ {ports} ];",
        "",
        f"  time.timeZone = {_nix_string(s.timezone)};",
        "",
        f"  services.openssh.enable = {_b(s.ssh)};",
        f"  services.openssh.settings.PasswordAuthentication = {_b(s.ssh_password_login)};",
        f"  services.openssh.settings.PermitRootLogin = {_nix_string(s.ssh_root_login)};",
        "",
        f"  hardware.bluetooth.enable = {_b(s.bluetooth)};",
        f"  services.pipewire.enable = {_b(s.sound)};",
        f"  virtualisation.docker.enable = {_b(s.docker)};",
        f"  nixpkgs.config.allowUnfree = {_b(s.allow_unfree)};",
    ]
    for user in s.users:
        lines += ["", *_render_user(user)]
    return lines


def render(config: MachineConfig) -> str:
    """The full contents of the machine's `nixync.nix`.

    Raises `InvalidPackageName` for a package or user name that cannot be safely
    written. Order is preserved: the server already sorts package lists, and sorting
    again here would hide a real difference between desired and reported state.
    """
    packages = " ".join(_checked(p, "package") for p in config.packages)
    lines = [
        HEADER + "{ config, pkgs, ... }:",
        "",
        "{",
        f"  environment.systemPackages = with pkgs; [ {packages} ];",
    ]
    if config.settings is not None:
        lines += ["", *_render_settings(config.settings)]
    lines.append("}")
    return "\n".join(lines) + "\n"
